-- Source: S&T and Corp GGF Bonus Team Upload File_consolidated.xlsx / Sheet1
-- Direct table insert only: grid hooks / Final rebuild / pending events are NOT executed.
-- Empty Comments are preserved as NULL, exactly as in Excel.
SET NOCOUNT ON;
SET XACT_ABORT ON;
DROP TABLE IF EXISTS #bonus_team_upload;
CREATE TABLE #bonus_team_upload (
    gpid VARCHAR(32), start_date DATE, end_date DATE,
    comp_group_name NVARCHAR(256), team_name NVARCHAR(MAX),
    new_team_name NVARCHAR(MAX), comments NVARCHAR(MAX), messages NVARCHAR(MAX)
);











































BEGIN TRY
    BEGIN TRANSACTION;
    -- Require exactly one dictionary match; never silently omit or multiply rows.
    IF EXISTS (
        SELECT 1 FROM #bonus_team_upload AS src
        WHERE (SELECT COUNT_BIG(*) FROM dbo.PEPSICO_CompGroup AS cg
               WHERE cg.CompGroupName = src.comp_group_name AND cg.FiscalYear = YEAR(src.start_date)) <> 1
    )
        THROW 50001, 'Missing or ambiguous Comp Group dictionary match. No rows inserted.', 1;

    IF EXISTS (
        SELECT 1 FROM #bonus_team_upload AS src
        INNER JOIN dbo.PEPSICO_CompGroup AS cg
            ON cg.CompGroupName = src.comp_group_name AND cg.FiscalYear = YEAR(src.start_date)
        WHERE src.team_name IS NOT NULL AND
            (SELECT COUNT_BIG(*) FROM dbo.PEPSICO_BonusTeam AS bt
             WHERE bt.TeamName = src.team_name AND bt.idCompGroup = cg.idCompGroup
                 AND bt.FiscalYear = YEAR(src.start_date)) <> 1
    )
        THROW 50002, 'Missing or ambiguous Bonus Team dictionary match. No rows inserted.', 1;

    SELECT src.gpid, src.start_date, src.end_date, cg.idCompGroup, bt.idBonusTeam,
        src.new_team_name, src.comments, src.messages, GETUTCDATE(), LEFT(ORIGINAL_LOGIN(), 50)
    FROM #bonus_team_upload AS src
    INNER JOIN dbo.PEPSICO_CompGroup AS cg
        ON cg.CompGroupName = src.comp_group_name AND cg.FiscalYear = YEAR(src.start_date)
    LEFT JOIN dbo.PEPSICO_BonusTeam AS bt
        ON bt.TeamName = src.team_name AND bt.idCompGroup = cg.idCompGroup
        AND bt.FiscalYear = YEAR(src.start_date);

    DECLARE @inserted_rows INT = @@ROWCOUNT;
    IF @inserted_rows <> (SELECT COUNT(*) FROM #bonus_team_upload)
        THROW 50003, 'Unexpected inserted row count. Transaction rolled back.', 1;
    COMMIT TRANSACTION;
    SELECT @inserted_rows AS inserted_rows;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
DROP TABLE IF EXISTS #bonus_team_upload;
